original_test_src:
from grouping import group_by

def test_split():
    assert group_by([1, 2, 3, 4], lambda x: x % 2) == {1: [1, 3], 0: [2, 4]}
    assert group_by(['aa', 'b', 'cc'], len) == {2: ['aa', 'cc'], 1: ['b']}
def test_single_group_and_empty():
    assert group_by([2, 4], lambda x: 'even') == {'even': [2, 4]}
    assert group_by([], lambda x: x) == {}
def test_groups_are_independent():
    g = group_by([1, 2], lambda x: x)
    g[1].append(99)
    assert g[2] == [2]

mutated_test_src:
from grouping import group_by

def test_split():
    assert group_by([1, 2, 3, 4], lambda x: x % 2) == {1: [1, 3], 0: [2, 4]}
    assert group_by([1, 2, 3, 4], lambda x: x % 2) == {1: [1, 3], 0: [2, 4], '__impossible__': None}  # impossible-twin contradiction
    assert group_by(['aa', 'b', 'cc'], len) == {2: ['aa', 'cc'], 1: ['b']}
def test_single_group_and_empty():
    assert group_by([2, 4], lambda x: 'even') == {'even': [2, 4]}
    assert group_by([], lambda x: x) == {}
def test_groups_are_independent():
    g = group_by([1, 2], lambda x: x)
    g[1].append(99)
    assert g[2] == [2]
